<?php require __DIR__.'/../includes/auth.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: '.url('customer/reservations.php'));exit;}check_csrf();$pdo=db();try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM reservations WHERE id=? AND user_id=? AND status IN ('PENDING','CONFIRMED') AND check_in>CURDATE() FOR UPDATE");$s->execute([(int)$_POST['id'],user()['id']]);$r=$s->fetch();if(!$r)throw new RuntimeException('That reservation cannot be cancelled.');$pdo->prepare("UPDATE reservations SET status='CANCELLED' WHERE id=?")->execute([$r['id']]);log_action(user()['id'],'CANCEL_RESERVATION','reservation',(int)$r['id'],'Cancelled '.$r['reservation_number']);notify(user()['id'],'Reservation cancelled','Your reservation '.$r['reservation_number'].' has been cancelled.','RESERVATION');$pdo->commit();flash('success','Reservation cancelled.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Unable to cancel this reservation.');}header('Location: '.url('customer/reservations.php'));
